VALUES ('eval_1792077017_5a1a80', 'bc09b03e-6e75-5453-ad3c-032fb44797a7', 'shivram@gmail.com', 'GS4', 10, 'किसी व्यक्ति के दृष्टिकोण के घटकों पर चर्चा कीजिये तथा प्रेरक संचार एवं सामाजिक प्रभाव किस प्रकार सकारात्मक मानसिकता विकसित करने में योगदान देते हैं? (150 शब्द) 10', 4.5, 45, '{"detected_question": "\u0915\u093f\u0938\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0915\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0918\u091f\u0915\u094b\u0902 \u092a\u0930 \u091a\u0930\u094d\u091a\u093e \u0915\u0940\u091c\u093f\u092f\u0947 \u0924\u0925\u093e \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u090f\u0935\u0902 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u093f\u0938 \u092a\u094d\u0930\u0915\u093e\u0930 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u093e\u0928\u0938\u093f\u0915\u0924\u093e \u0935\u093f\u0915\u0938\u093f\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u092f\u094b\u0917\u0926\u093e\u0928 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902? (150 \u0936\u092c\u094d\u0926) 10", "detected_paper": "GS4", "max_marks": 10, "overall_score": 4.5, "percentile_verdict": "\u092a\u094d\u0930\u0924\u093f\u0938\u094d\u092a\u0930\u094d\u0927\u0940 \u092a\u094d\u0930\u092f\u093e\u0938 (\u0936\u0940\u0930\u094d\u0937 15% \u0905\u0902\u0915)", "executive_summary": "\u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u0947 ABC \u092e\u0949\u0921\u0932 \u0914\u0930 \u0918\u091f\u0915\u094b\u0902 \u0915\u094b \u0906\u0930\u0947\u0916\u094b\u0902 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u093f\u0924 \u0915\u093f\u092f\u093e \u0939\u0948\u0964 \u092e\u0941\u0916\u094d\u092f \u092d\u093e\u0917 \u092e\u0947\u0902 \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u09