\u2713 **\u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937 \u0915\u093e \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 (Closing Synthesis)**: \u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0921\u0940. \u0930\u0942\u0935\u0947\u0932\u094d\u091f \u0915\u0947 \u0938\u0941\u0902\u0926\u0930 \u0909\u0926\u094d\u0927\u0930\u0923 \u0915\u0947 \u0938\u093e\u0925 \u0909\u0924\u094d\u0924\u0930 \u0915\u093e \u0938\u092e\u093e\u092a\u0928 \u0915\u093f\u092f\u093e \u0939\u0948, \u091c\u094b \u0928\u0940\u0924\u093f\u0936\u093e\u0938\u094d\u0924\u094d\u0930 \u0915\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0938\u0947 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u0939\u0948\u0964"}], "intro_audit": {"intro_score": 1.0, "intro_max": 1.5, "intro_archetype": "\u092a\u0930\u093f\u092d\u093e\u0937\u093e-\u0906\u0927\u093e\u0930\u093f\u0924", "topic_vs_question_relevance": "\u0938\u0940\u0927\u0947 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u0940 \u092e\u0942\u0932 \u0905\u0935\u0927\u093e\u0930\u0923\u093e (\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0905\u0930\u094d\u0925) \u0915\u094b \u0932\u0915\u094d\u0937\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948", "current_critique": "\u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u094b \u092c\u0939\u0941\u0924 \u0939\u0940 \u0938\u0930\u0932 \u0914\u0930 \u0938\u091f\u0940\u0915 \u0936\u092c\u094d\u0926\u094b\u0902 \u092e\u0947\u0902 \u092a\u0930\u093f\u092d\u093e\u0937\u093f\u0924 \u0915\u093f\u092f\u093e \u0939\u0948 \u0924\u0925\u093e \u0909\u0926\u093e\u0939\u0930\u0923 (\u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915, \u0908\u092e\u093e\u0928\u0926\u093e\u0930\u0940 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915) \u0926\u0947\u0915\u0930 \u0905\u092a\u0928\u0940 \u092c\u093e\u0924 \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0915\u093f\u092f\u093e \u0939\u0948\u0964", "model_intro_rewrite": "\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u093f\u0938\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f, \u0935\u0938\u094d\u0924\u0941 \u092f\u093e \u0918\u091f\u0928\u093e \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u094d\u0925\u093e\u092f\u0940 \u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 \u0914\u0930 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f (ABC Model) \u0939\u0948, \u091c\u094b \u0909\u0938\u0915\u0947 \u0928\u093f\u0930\u094d\u0923\u092f\u094b\u0902 \u0915\u094b \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964"}, "body_audit": {"body_score": 3.0, "body_max": 7.0, "strengths": ["**\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0924\u0940\u0928\u094b\u0902 \u0918\u091f\u0915\u094b\u0902 (\u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, (\u092a\u0943\u0937\u094d\u0920 1)**: \u0906\u092a\u0928\u0947 \u0909\u0924\u094d\u0924\u0930-\u092a\u0941\u0938\u094d\u0924\u093f\u0915\u093e \u092e\u0947\u0902 **\u0915\u093f\u0938\u0940 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0935\u093f\u0937\u092f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092f\u093e \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092d\u093e\u0935 \u0915\u0940 \u0924\u0940\u0935\u094d\u0930\u0924\u093e \u0938\u0947 \u0939\u0948\u0964 \u0909\u0926\u093e\u0966 \u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f** \u0915\u093e \u0909\u0932\u094d\u0932\u0947\u0916 \u0915\u0930 \u0907\u0938 \u0906\u092f\u093e\u092e \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0928\u093f\u0930\u0942\u092a\u093f\u0924 \u0915\u093f\u092f\u093e \u0939\u0948\u0964 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915, \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915) \u0915\u094b \u0906\u0930\u0947\u0916/\u092b\u094d\u0932\u094b\u091a\u093e\u0930\u094d\u091f \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0936\u093e\u0928\u0926\u093e\u0930 \u0922\u0902\u0917 \u0938\u0947 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964 \u092f\u0939 \u0938\u0941\u0926\u0943\u0922\u093c \u0905\u0935\u0927\u093e\u0930\u0923\u093e\u0924\u094d\u092e\u0915 \u0938\u092e\u091d \u0915\u094b \u0926\u0930\u094d\u0936\u093e\u0924\u093e \u0939\u0948 \u0924\u0925\u093e \u092e\u0941\u0916\u094d\u092f \u092e\u093e\u0902\u0917 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0905\u0902\u0915 \u0926\u093f\u0932\u093e\u0924\u093e \u0939\u0948\u0964", "**\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u094b \u0938\u092e\u091d\u093e\u0928\u0947 \u0915\u0947 (\u092a\u0943\u0937\u094d\u0920 1\u20132)**: \u0932\u093f\u090f IAS \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 (\u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932, \u0938\u094c\u0930\u092d \u0915\u0941\u092e\u093e\u0930, \u0930\u093e\u0939\u0941\u0932 \u0915\u0941\u092e\u093e\u0930) \u0914\u0930 \u092e\u0939\u093e\u0924\u094d\u092e\u093e \u0917\u093e\u0902\u0927\u0940 \u0915\u0947 \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 \u0915\u093e \u092c\u0939\u0941\u0924 \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964", "**\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u093e \u0924\u093e\u0924\u094d\u092a\u0930\u094d\u092f (Page 1)**: \u0915\u093f\u0938\u0940 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0935\u093f\u0937\u092f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092f\u093e \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092d\u093e\u0935 \u0915\u0940 \u0924\u0940\u0935\u094d\u0930\u0924\u093e \u0938\u0947 \u0939\u0948\u0964 \u0909\u0926\u093e\u0966 \u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f.... \u0905\u0935\u0927\u093e\u0930\u0923\u093e \u0915\u094b \u092c\u0939\u0941\u0924 \u0939\u0940 \u0938\u091f\u0940\u0915 \u0914\u0930 \u0938\u0930\u0932 \u0930\u0942\u092a \u092e\u0947\u0902 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964", "**\u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u090f\u0935\u0902 \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 \u0918\u091f\u0915 (Page 1)**: \u092b\u094d\u0932\u094b\u091a\u093e\u0930\u094d\u091f \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0924\u0940\u0928\u094b\u0902 \u0918\u091f\u0915\u094b\u0902 (\u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915, \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915) \u0915\u093e \u0938\u0941\u0902\u0926\u0930 \u0935\u0930\u094d\u0917\u0940\u0915\u0930\u0923 \u0914\u0930 \u092e\u093e\u0901 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923\u0964. \u0906\u0930\u0947\u0916\u0940\u092f \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u0905\u0924\u094d\u092f\u0902\u0924 \u0938\u0930\u093e\u0939\u0928\u0940\u092f \u0939\u0948, \u091c\u093f\u0938\u0938\u0947 \u0909\u0924\u094d\u0924\u0930 \u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f\u0915\u0930\u0923 \u092c\u0939\u0941\u0924 \u0938\u0941\u0927\u0930 \u0917\u092f\u093e \u0939\u0948\u0964", "**\u092a\u094d\u0930\u0936\u093e\u0938\u0928\u093f\u0915 \u090f\u0935\u0902 \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923 (Page 2)**: IAS \u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932, \u0906\u0936\u093e \u0915\u093e\u0930\u094d\u092f\u0915\u0930\u094d\u0924\u093e, IAS \u0938\u094c\u0930\u092e \u0915\u0941\u092e\u093e\u0930, IAS \u0930\u093e\u0939\u0941\u0932 \u0915\u0941\u092e\u093e\u0930 \u0914\u0930 \u092e\u0939\u093e\u0924\u094d\u092e\u093e \u0917\u093e\u0902\u0927\u0940 \u0915\u0947 \u0909\u0926\u093e\u0939\u0930\u0923\u0964. \u0938\u092e\u0938\u093e\u092e\u092f\u093f\u0915 \u0914\u0930 \u092a\u094d\u0930\u0936\u093e\u0938\u0928\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 \u0915\u093e \u092f\u0939 \u092c\u0939\u0941\u0906\u092f\u093e\u092e\u0940 \u092a\u094d\u0930\u092f\u094b\u0917 \u0907\u0938 \u0909\u0924\u094d\u0924\u0930 \u0915\u0940 \u0938\u092c\u0938\u0947 \u092c\u0921\u093c\u0940 \u0924\u093e\u0915\u0924 \u0939\u0948\u0964"], "critical_gaps": ["**\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0902\u0924\u094d\u0930 (Page 1\u20132)**: (\u091c\u0948\u0938\u0947 Credibility, Attractiveness, Persuasive message design) \u0915\u093e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0938\u0940\u092e\u093f\u0924 \u0939\u0948\u0964", "**\u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 (Social Influence) \u0915\u0947 (Page 2)**: \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0930\u0942\u092a\u094b\u0902 (Compliance, Identification, Internalization) \u0915\u094b \u0905\u0932\u0917 \u0938\u0947 \u0938\u094d\u092a\u0937\u094d\u091f \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964"], "missing_dimensions": ["**[\u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u092e\u0949\u0921\u0932]**: \u090f\u0932\u0935\u0941\u0921 \u0914\u0930 \u092a\u0947\u091f\u094d\u0930\u0940 \u0915\u093e ''\u0935\u093f\u0938\u094d\u0924\u093e\u0930 \u0938\u0902\u092d\u093e\u0935\u0928\u093e \u092e\u0949\u0921\u0932'' (Elaboration Likelihood Model - ELM) \u0915\u093e \u0938\u0902\u0915\u094d\u0937\u093f\u092a\u094d\u0924 \u0938\u0902\u0926\u0930\u094d\u092d\u0964", "**[\u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935]**: \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u093e\u0928\u0938\u093f\u0915\u0924\u093e \u0915\u0947 \u0935\u093f\u0915\u093e\u0938 \u092e\u0947\u0902 \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 \u092c\u0941\u0926\u094d\u0927\u093f\u092e\u0924\u094d\u0924\u093e (Emotional Intelligence) \u0915\u0940 \u092d\u0942\u092e\u093f\u0915\u093e\u0964"], "examiner_guidance": "\u092e\u0941\u0916\u094d\u092f \u092d\u093e\u0917 \u092e\u0947\u0902 \u0906\u0930\u0947\u0916 \u0915\u0947 \u0938\u093e\u0925-\u0938\u093e\u0925 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0936\u092c\u094d\u0926\u093e\u0935\u0932\u0940 \u0914\u0930 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0938\u093f\u0926\u094d\u0927\u093e\u0902\u0924\u094b\u0902 (\u091c\u0948\u0938\u0947 \u0915\u0947\u0932\u094d\u0935\u093f\u0928 \u0915\u0947 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u0947 \u0924\u0940\u0928 \u0938\u094d\u0924\u0930) \u0915\u094b \u0936\u093e\u092e\u093f\u0932 \u0915\u0930\u0947\u0902\u0964", "overall_assessment": "\u092e\u0941\u0916\u094d\u092f \u092d\u093e\u0917 (Body) \u092e\u0947\u0902 \u0906\u092a\u0928\u0947 **\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0924\u0940\u0928\u094b\u0902 \u0918\u091f\u0915\u094b\u0902 (\u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, (\u092a\u0943\u0937\u094d\u0920 1)** \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u0930 **3.0 / 7.0 \u0905\u0902\u0915** \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u093f\u090f \u0939\u0948\u0902\u0964 \u0905\u0917\u0932\u0947 **+1.5 \u0938\u0947 +2.5 \u0905\u0902\u0915** \u0915\u0947 \u0938\u094d\u0924\u0930 \u0924\u0915 \u092a\u0939\u0941\u0901\u091a\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f **\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0902\u0924\u094d\u0930 (Page 1\u20132)** \u092a\u0930 \u0935\u093f\u0936\u0947\u0937 \u0927\u094d\u092f\u093e\u0928 \u0926\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0936\u094d\u0928-\u0935\u093f\u0936\u093f\u0937\u094d\u091f \u0938\u093e\u0915\u094d\u0937\u094d\u092f\u094b\u0902 \u0938\u0947 \u092a\u0941\u0937\u094d\u091f \u0915\u0930\u0947\u0902\u0964"}, "conclusion_audit": {"conclusion_score": 0.5, "conclusion_max": 1.5, "conclusion_archetype": "\u0928\u0948\u0924\u093f\u0915 / \u092e\u093e\u0928\u0915\u0940\u092f", "failure_mode": "\u0915\u094b\u0908 \u0928\u0939\u0940\u0902 (\u0938\u0902\u0924\u0941\u0932\u093f\u0924)", "current_critique": "\u2713 **\u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937 \u0915\u093e \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 (Closing Synthesis)**: \u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0921\u0940. \u0930\u0942\u0935\u0947\u0932\u094d\u091f \u0915\u0947 \u0938\u0941\u0902\u0926\u0930 \u0909\u0926\u094d\u0927\u0930\u0923 \u0915\u0947 \u0938\u093e\u0925 \u0909\u0924\u094d\u0924\u0930 \u0915\u093e \u0938\u092e\u093e\u092a\u0928 \u0915\u093f\u092f\u093e \u0939\u0948, \u091c\u094b \u0928\u0940\u0924\u093f\u0936\u093e\u0938\u094d\u0924\u094d\u0930 \u0915\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0938\u0947 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u0939\u0948\u0964", "model_conclusion_rewrite": "**\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947**: \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0902\u0924\u094d\u0930 (\u091c\u0948\u0938\u0947 Credibility, Attractiveness, Persuasive message design) \u0915\u093e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0938\u0940\u092e\u093f\u0924 \u0939\u0948\u0964 \u2022 **\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u094b**: \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u094b \u0938\u092e\u091d\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f IAS \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 (\u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932, \u0938\u094c\u0930\u092d \u0915\u0941\u092e\u093e\u0930, \u0930\u093e\u0939\u0941\u0932 \u0915\u0941\u092e\u093e\u0930) \u0914\u0930 \u092e\u0939\u093e\u0924\u094d\u092e\u093e \u0917\u093e\u0902\u0927\u0940 \u0915\u0947 \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 \u0915\u093e \u092c\u0939\u0941\u0924 \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964", "is_unwritten": false, "score": 0.5}, "missing_keywords_cards": [{"number": 1, "term": "ABC Model (Affective, Behavioural, Cognitive)", "thinker": "\u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923", "domain_or_thinker": "\u26a1 Shallow Mention \u2014 Analytical Upgrade Needed", "definition": "You cited **ABC Model (Affective, Behavioural, Cognitive)** in passing\u2014substantiate its core analytical application: \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0924\u0940\u0928 \u092a\u0930\u0938\u094d\u092a\u0930 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u0918\u091f\u0915: \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 (\u092d\u093e\u0935), \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915 (\u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f) \u0914\u0930 \u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915 (\u0935\u093f\u0936\u094d\u0935\u093e\u0938)\u0964", "where_to_use": "Build directly on your existing ABC Model (Affective, Behavioural, Cognitive) point on your answer sheet.", "how_to_use_one_line": "\u0935\u093e\u0915\u094d\u092f \u092e\u0947\u0902 \u0907\u0938 \u092a\u094d\u0930\u0915\u093e\u0930 \u091c\u094b\u0921\u093c\u0947\u0902: ''\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u092e\u0942\u0932\u0924\u0903 ABC \u092e\u0949\u0921\u0932 (Affective, Behavioural, Cognitive) \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924 \u0939\u094b\u0924\u093e \u0939\u0948\u0964''"}, {"number": 2, "term": "Elaboration Likelihood Model (ELM)", "thinker": "\u092a\u0947\u091f\u094d\u0930\u0940 \u090f\u0935\u0902 \u0915\u0948\u0938\u093f\u0913\u092a\u094b", "domain_or_thinker": "\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 (Persuasion)", "definition": "\u092f\u0939 \u092e\u0949\u0921\u0932 \u092c\u0924\u093e\u0924\u093e \u0939\u0948 \u0915\u093f \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0915\u0947\u0902\u0926\u094d\u0930\u0940\u092f \u092f\u093e \u092a\u0930\u093f\u0927\u0940\u092f \u092e\u093e\u0930\u094d\u0917 \u0938\u0947 \u0938\u0902\u0926\u0947\u0936 \u0915\u094b \u0915\u0948\u0938\u0947 \u0917\u094d\u0930\u0939\u0923 \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u0926\u0943\u0937\u094d\u091f\u093f\u0915