0930\u094d\u0937", "title": "\u0921\u0940. \u0930\u0942\u0935\u0947\u0932\u094d\u091f \u0915\u093e \u0915\u0925\u0928", "what_you_wrote": "\u0921\u0940. \u0930\u0942\u0935\u0947\u0932\u094d\u091f \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 - ''\u0905\u092d\u093f\u0935\u0943\u0924\u094d\u0924\u093f \u092c\u0926\u0932\u0915\u0930 \u0906\u092a \u0905\u092a\u0928\u0940 \u092a\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u093f \u092c\u0926\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964''", "examiner_verdict": "\u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0914\u0930 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u0909\u0926\u094d\u0927\u0930\u0923 \u0915\u0947 \u0938\u093e\u0925 \u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u0938\u092e\u093e\u092a\u0928\u0964", "credit_badge": "\u2713 +0.5M \u0905\u0902\u0915 \u092e\u093f\u0932\u0947", "is_positive": true}], "rubric_scores": {"intro_score": 1.0, "intro_max": 1.5, "core_demand_score": 2.0, "core_demand_max": 4.5, "value_add_score": 0.5, "value_add_max": 1.5, "presentation_score": 0.5, "presentation_max": 1.0, "conclusion_score": 0.5, "conclusion_max": 1.5}, "directive_compliance": {"directive": "\u091a\u0930\u094d\u091a\u093e \u0915\u0940\u091c\u093f\u090f", "is_compliant": true, "compliance_verdict": "\u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0918\u091f\u0915\u094b\u0902 \u0914\u0930 \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0940 \u092d\u0942\u092e\u093f\u0915\u093e \u092a\u0930 \u092a\u094d\u0930\u093e\u0938\u0902\u0917\u093f\u0915 \u091a\u0930\u094d\u091a\u093e \u0915\u0940 \u0939\u0948\u0964", "examiner_advice": "\u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u092a\u094d\u0930\u0936\u093e\u0938\u0928\u093f\u0915 \u0914\u0930 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0906\u092f\u093e\u092e\u094b\u0902 \u0915\u094b \u0938\u0902\u0924\u0941\u0932\u093f\u0924 \u0930\u0916\u0924\u0947 \u0939\u0941\u090f \u0907\u0938\u0940 \u092a\u094d\u0930\u0915\u093e\u0930 \u0915\u0947 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 \u0915\u093e \u0905\u092d\u094d\u092f\u093e\u0938 \u091c\u093e\u0930\u0940 \u0930\u0916\u0947\u0902\u0964"}, "transcribed_text": "[Page 1]\n\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u093e \u0924\u093e\u0924\u094d\u092a\u0930\u094d\u092f \u0915\u093f\u0938\u0940 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0935\u093f\u0937\u092f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092f\u093e \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092d\u093e\u0935 \u0915\u0940 \u0924\u0940\u0935\u094d\u0930\u0924\u093e \u0938\u0947 \u0939\u0948\u0964 \u0909\u0926\u093e\u0966 \u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f - \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f, \u0908\u092e\u093e\u0928\u0926\u093e\u0930\u0940 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f - \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f\u0964\n[\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0918\u091f\u0915 - \u092b\u094d\u0932\u094b\u091a\u093e\u0930\u094d\u091f]\n(1) \u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915: \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0935\u093f\u0937\u092f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0938\u0942\u091a\u0928\u093e \u092f\u093e \u091c\u093e\u0928\u0915\u093e\u0930\u0940 (\u0909\u0926\u093e\u0966 \u092e\u093e\u0901 \u0939\u092e\u093e\u0930\u0940 \u092a\u094d\u0930\u0925\u092e \u0936\u093f\u0915\u094d\u0937\u093f\u0915\u093e \u0939\u094b\u0924\u0940 \u0939\u0948, \u092b\u0932\u0924\u0903 \u092e\u093e\u0901 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0932\u094b\u0917\u094b\u0902 \u092e\u0947\u0902 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923\u0964)\n(2) \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915: \u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u0935\u093f\u0930\u0941\u0926\u094d\u0927 \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (\u0909\u0926\u093e\u0966 IAS \u0905\u0936\u094b\u0915 \u0916\u0947\u092e\u0915\u093e \u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u091c\u092e\u0940\u0928 \u0915\u0947 \u092e\u094d\u092f\u0942\u091f\u0947\u0936\u0928 \u0915\u093e \u0930\u0926\u094d\u0926 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u093e\u0964)\n(3) \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915: \u0915\u094d\u0937\u0947\u0924\u094d\u0930\u094b\u0902 \u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u0936\u094d\u0935\u0947\u0924\u094b\u0902 \u0915\u094b \u0905\u0938\u0915\u094d\u0937\u092e \u092e\u093e\u0928\u093e \u091c\u093e\u0928\u093e (\u0909\u0926\u093e\u0966 White man''s burden theory.)\n\n[Page 2]\n\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 (\u0907\u0938 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u093e\u0928\u0938\u093f\u0915\u0924\u093e \u0915\u094b \u0935\u093f\u0915\u0938\u093f\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u092d\u0942\u092e\u093f\u0915\u093e):\n(1) IAS \u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932 \u0926\u094d\u0935\u093e\u0930\u093e COVID-19 \u0915\u093e\u0932 \u092e\u0947\u0902 \u091f\u0940\u0915\u093e\u0915\u0930\u0923 \u0939\u0947\u0924\u0941 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u0935\u0940\u0921\u093f\u092f\u094b \u091c\u093e\u0930\u0940 \u0915\u0930 \u0924\u0925\u093e \u092a\u094d\u0930\u0936\u0902\u0938\u093e \u0935 \u092a\u0941\u0930\u0938\u094d\u0915\u093e\u0930 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0932\u094b\u0917\u094b\u0902 \u0915\u094b \u091c\u093e\u0917\u0930\u0942\u0915 \u0915\u0930\u0928\u093e\u0964\n(2) \u0906\u0936\u093e \u0915\u093e\u0930\u094d\u092f\u0915\u0930\u094d\u0924\u093e ''\u092e\u091f\u093f\u0932\u094d\u0915\u093e \u0915\u0941\u0932\u094d\u0932\u0942'' \u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u0932\u094b\u0917\u094b\u0902 \u0915\u094b \u0924\u0902\u0924\u094d\u0930-\u092e\u0902\u0924\u094d\u0930 \u0915\u0940 \u091c\u0917\u0939 \u092a\u0930 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915\u0940\u092f \u092a\u0930\u093e\u092e\u0930\u094d\u0936 \u0939\u0947\u0924\u0941 \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n(3) IAS \u0938\u094c\u0930\u092d \u0915\u0941\u092e\u093e\u0930 \u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e ''Launch with the Collector'' \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092f\u0941\u0935\u093e\u0913\u0902 \u0915\u094b \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u092e\u0947\u0902 \u092d\u093e\u0917\u0940\u0926\u093e\u0930 \u092c\u0928\u0928\u0947 \u0939\u0947\u0924\u0941 \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n(4) IAS \u0930\u093e\u0939\u0941\u0932 \u0915\u0941\u092e\u093e\u0930 \u0915\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u0917\u094b\u092a\u093e\u0932\u0917\u0902\u091c \u092e\u0947\u0902 ''Mid-day-Meal'' \u0915\u093e \u0916\u093e\u0928\u093e \u0938\u094d\u0935\u092f\u0902 \u0916\u093e\u0915\u0930 \u0905\u0928\u094d\u092f \u091b\u093e\u0924\u094d\u0930\u094b\u0902 \u0915\u094b \u092d\u0940 \u092e\u0927\u094d\u092f\u093e\u0939\u094d\u0928 \u092d\u094b\u091c\u0928 \u0915\u0930\u0928\u0947 \u0939\u0947\u0924\u0941 \u092a\u094d\u0930\u0947\u0930\u093f\u0924 \u0915\u0930\u0928\u093e\u0964\n(5) \u092e\u0939\u093e\u0924\u094d\u092e\u093e \u0917\u093e\u0902\u0927\u0940 \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u0940\u0924\u093e \u0914\u0930 \u0938\u093e\u0935\u093f\u0924\u094d\u0930\u0940 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923 \u0926\u0947\u0915\u0930 \u092e\u0939\u093f\u0932\u093e\u0913\u0902 \u0915\u094b \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u0906\u0902\u0926\u094b\u0932\u0928 \u0938\u0947 \u091c\u094b\u0921\u093c\u0928\u093e\u0964\n\u0921\u0940. \u0930\u0942\u0935\u0947\u0932\u094d\u091f \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 - ''\u0905\u092d\u093f\u0935\u0943\u0924\u094d\u0924\u093f \u092c\u0926\u0932\u0915\u0930 \u0906\u092a \u0905\u092a\u0928\u0940 \u092a\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u093f \u092c\u0926\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964''", "full_model_answer": "\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u093f\u0938\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f, \u0935\u0938\u094d\u0924\u0941 \u092f\u093e \u0918\u091f\u0928\u093e \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u094d\u0925\u093e\u092f\u0940 \u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915, \u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 \u0914\u0930 \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f (ABC Model) \u0939\u0948, \u091c\u094b \u0909\u0938\u0915\u0947 \u0928\u093f\u0930\u094d\u0923\u092f\u094b\u0902 \u0914\u0930 \u0906\u091a\u0930\u0923 \u0915\u094b \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u092f\u0939 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092f\u093e \u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0939\u094b \u0938\u0915\u0924\u0940 \u0939\u0948\u0964\n\n**\u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u092a\u094d\u0930\u092e\u0941\u0916 \u0918\u091f\u0915 (ABC Model):**\n\u2022 **\u0938\u0902\u091c\u094d\u091e\u093e\u0928\u093e\u0924\u094d\u092e\u0915 \u0918\u091f\u0915 (Cognitive)**: \u092f\u0939 \u0935\u093f\u0936\u094d\u0935\u093e\u0938, \u091c\u094d\u091e\u093e\u0928 \u0914\u0930 \u0938\u0942\u091a\u0928\u093e\u0913\u0902 \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924 \u0939\u094b\u0924\u093e \u0939\u0948 (\u0909\u0926\u093e\u0966 \u0936\u093f\u0915\u094d\u0937\u093e \u0926\u094d\u0935\u093e\u0930\u093e \u092a\u0930\u094d\u092f\u093e\u0935\u0930\u0923 \u0938\u0902\u0930\u0915\u094d\u0937\u0923 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0935\u093f\u0915\u0938\u093f\u0924 \u0939\u094b\u0928\u093e)\u0964\n\u2022 **\u092d\u093e\u0935\u0928\u093e\u0924\u094d\u092e\u0915 \u0918\u091f\u0915 (Affective)**: \u092f\u0939 \u0915\u093f\u0938\u0940 \u0935\u093f\u0937\u092f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u092d\u093e\u0935\u0928\u093e\u0913\u0902 \u092f\u093e \u0930\u093e\u0917-\u0935\u093f\u0930\u093e\u0917 \u0938\u0947 \u091c\u0941\u0921\u093c\u093e \u0939\u094b\u0924\u093e \u0939\u0948 (\u0909\u0926\u093e\u0966 \u0932\u094b\u0915 \u0938\u0947\u0935\u0915\u094b\u0902 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u091c\u0928\u0924\u093e \u0915\u093e \u0938\u0939\u093e\u0928\u0941\u092d\u0942\u0924\u093f\u092a\u0942\u0930\u094d\u0923 \u092f\u093e \u0938\u0902\u0936\u092f\u093e\u0924\u094d\u092e\u0915 \u092d\u093e\u0935)\u0964\n\u2022 **\u0935\u094d\u092f\u0935\u0939\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0918\u091f\u0915 (Behavioural)**: \u092f\u0939 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0915\u093e\u0930\u094d\u092f \u0915\u0930\u0928\u0947 \u0915\u0940 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f \u0915\u094b \u0926\u0930\u094d\u0936\u093e\u0924\u093e \u0939\u0948 (\u0909\u0926\u093e\u0966 IAS \u0905\u0936\u094b\u0915 \u0916\u0947\u092e\u0915\u093e \u0926\u094d\u0935\u093e\u0930\u093e \u092d\u094d\u0930\u0937\u094d\u091f\u093e\u091a\u093e\u0930 \u0915\u0947 \u0935\u093f\u0930\u0941\u0926\u094d\u0927 \u0915\u0920\u094b\u0930 \u092a\u094d\u0930\u0936\u093e\u0938\u0928\u093f\u0915 \u0915\u0926\u092e \u0909\u0920\u093e\u0928\u093e)\u0964\n\n**\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u0940 \u092d\u0942\u092e\u093f\u0915\u093e:**\n\u2022 **\u0935\u093f\u0936\u094d\u0935\u093e\u0938\u093e\u0930\u094d\u0939\u0924\u093e \u0914\u0930 \u0935\u093f\u0936\u094d\u0935\u0938\u0928\u0940\u092f\u0924\u093e (Credibility)**: COVID-19 \u091f\u0940\u0915\u093e\u0915\u0930\u0923 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 IAS \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u0935\u0940\u0921\u093f\u092f\u094b \u091c\u093e\u0930\u0940 \u0915\u0930 \u092d\u094d\u0930\u093e\u0902\u0924\u093f\u092f\u094b\u0902 \u0915\u094b \u0926\u0942\u0930 \u0915\u0930\u0928\u093e\u0964\n\u2022 **\u0928\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0930\u0942\u0922\u093c\u093f\u0935\u093e\u0926\u093f\u0924\u093e \u0915\u093e \u0916\u0902\u0921\u0928**: \u0906\u0936\u093e \u0915\u093e\u0930\u094d\u092f\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0926\u094d\u0935\u093e\u0930\u093e \u0905\u0902\u0927\u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0915\u0947 \u0938\u094d\u0925\u093e\u0928 \u092a\u0930 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915\u0940\u092f \u092a\u0930\u093e\u092e\u0930\u094d\u0936 (Institutional Delivery) \u0915\u094b \u092c\u0922\u093c\u093e\u0935\u093e \u0926\u0947\u0928\u093e\u0964\n\u2022 **\u092f\u0941\u0935\u093e \u0938\u0939\u092d\u093e\u0917\u093f\u0924\u093e**: ''Launch with the Collector'' \u091c\u0948\u0938\u0940 \u092a\u0939\u0932\u094b\u0902 \u0938\u0947 \u092f\u0941\u0935\u093e\u0913\u0902 \u092e\u0947\u0902 \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0915\u0940 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u092e\u093e\u0928\u0938\u093f\u0915\u0924\u093e \u0915\u093e \u0938\u0943\u091c\u0928\u0964\n\u2022 **\u0930\u094b\u0932 \u092e\u0949\u0921\u0932 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923**: \u0928\u0947\u0924\u0943\u0924\u094d\u0935\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u094d\u0935\u092f\u0902 \u0906\u091a\u0930\u0923 \u0915\u0930 \u092e\u093f\u0938\u093e\u0932 \u092a\u0947\u0936 \u0915\u0930\u0928\u093e (\u0909\u0926\u093e\u0966 \u0917\u094b\u092a\u093e\u0932\u0917\u0902\u091c \u092e\u0947\u0902 \u092e\u093f\u0921-\u0921\u0947 \u092e\u0940\u0932 \u0915\u093e \u0938\u094d\u0935\u092f\u0902 \u0938\u0947\u0935\u0928)\u0964\n\n\u0905\u0924\u0903 \u0938\u094d\u092a\u0937\u094d\u091f \u0939\u0948 \u0915\u093f \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0938\u0902\u091a\u093e\u0930 \u0914\u0930 \u0938\u0915\u093e\u0930\u093e\u0924\u094d\u092e\u0915 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 (Social Influence) \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u091c\u0928\u092e\u093e\u0928\u0938 \u0915\u0940 \u0905\u092d\u093f\u0935\u0943\u0924\u094d\u0924\u093f \u0915\u094b \u092c\u0926\u0932\u0915\u0930 \u090f\u0915 \u092a\u094d\u0930\u092c\u0941\u0926\u094d\u0927 \u0914\u0930 \u092a\u094d\u0930\u0917\u0924\u093f\u0936\u0940\u0932 \u0938\u092e\u093e\u091c \u0915\u093e \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964\n\n\u2022 **\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947**: \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u0947 \u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0924\u0902\u0924\u094d\u0930 (\u091c\u0948\u0938\u0947 Credibility, Attractiveness, Persuasive message design) \u0915\u093e \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0938\u0940\u092e\u093f\u0924 \u0939\u0948\u0964\n\u2022 **\u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u094b**: \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0915\u094b \u0938\u092e\u091d\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f IAS \u0905\u0927\u093f\u0915\u093e\u0930\u093f\u092f\u094b\u0902 (\u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932, \u0938\u094c\u0930\u092d \u0915\u0941\u092e\u093e\u0930, \u0930\u093e\u0939\u0941\u0932 \u0915\u0941\u092e\u093e\u0930) \u0914\u0930 \u092e\u0939\u093e\u0924\u094d\u092e\u093e \u0917\u093e\u0902\u0927\u0940 \u0915\u0947 \u0910\u0924\u093f\u0939\u093e\u0938\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 \u0915\u093e \u092c\u0939\u0941\u0924 \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964", "is_hindi": true, "medium": "hindi", "model_answer_meta": {"is_adaptive": true, "word_count": 286, "target_words": 150, "point_count": 9, "badge_text": "\u2728 Topper Synthesis (Candidate Points Retained + High-Yield Dimensions)", "badge_text_hindi": "\u2728 \u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940-\u0938\u0902\u0935\u0930\u094d\u0927\u093f\u0924 \u092e\u0949\u0921\u0932 \u0909\u0924\u094d\u0924\u0930 (\u092e\u093e\u0928\u094d\u092f \u092c\u093f\u0902\u0926\u0941 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 + \u092a\u0930\u0940\u0915\u094d\u0937\u0915 \u092e\u0942\u0932\u094d\u092f-\u0938\u0902\u0935\u0930\u094d\u0927\u0928)"}, "keyword_toolkit_title": "Essential Thinkers, Philosophies & Ethical Frameworks (Missing Keywords)", "value_add_checklist": {"category_1": {"title": "Philosophical Doctrines & Moral Thinkers", "items": []}, "category_2": {"title": "2nd ARC Recommendations & Civil Service Values", "items": []}, "category_3": {"title": "Applied Governance Case Studies & Real-World Exemplars", "items": []}, "category_4": {"title": "Recommended Exam-Hall Micro-Diagram / Map", "items": []}}, "examiner_overall_verdict": "\u0905\u092d\u094d\u092f\u0930\u094d\u0925\u0940 \u0928\u0947 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Attitude) \u0915\u0947 ABC \u092e\u0949\u0921\u0932 \u0914\u0930 \u0918\u091f\u0915\u094b\u0902 \u0915\u094b \u0906\u0930\u0947\u0916\u094b\u0902 \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u093f\u0924 \u0915\u093f\u092f\u093e \u0939\u0948\u0964 \u092e\u0941\u0916\u094d\u092f \u092d\u093e\u0917 \u092e\u0947\u0902 \u092a\u094d\u0930\u0947\u0930\u0915 \u0938\u0902\u091a\u093e\u0930 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u092a\u094d\u0930\u092d\u093e\u0935 \u0915\u0940 \u092d\u0942\u092e\u093f\u0915\u093e \u0915\u094b \u092a\u094d\u0930\u0936\u093e\u0938\u0928\u093f\u0915 \u0909\u0926\u093e\u0939\u0930\u0923\u094b\u0902 (IAS \u0938\u094d\u092e\u093f\u0924\u093e \u0938\u092d\u0930\u0935\u093e\u0932, IAS \u0938\u094c\u0930\u092e \u0915\u0941\u092e\u093e\u0930) \u0915\u0947 \u0938\u093e\u0925 \u0938\u092e\u091d\u093e\u092f\u093e \u0917\u092f\u093e \u0939\u0948, \u091c\u094b \u090f\u0915 \u0909\u0924\u094d\u0915\u0943\u0937\u094d\u091f \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u0939\u0948\u0964 \u0939\u093e\u0932\u093e\u0902\u0915\u093f, \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 \u0917\u0939\u0930\u093e\u0908 \u0914\u0930 \u0935\u093f\u0927\u093f\u0915/\u092e\u0928\u094b\u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0936\u092c\u